-- NEWSTART ONLY. Run in Supabase SQL editor after review. No BAA tables are modified.
create extension if not exists pgcrypto;
create table if not exists public.pal_ns_houses (id integer primary key check(id between 1 and 11),tenant text not null default 'newstart' check(tenant='newstart'),name text not null,accounting_code text,created_at timestamptz not null default now());
insert into public.pal_ns_houses(id,name) select n,case when n=11 then 'Office' else 'House '||n end from generate_series(1,11) n on conflict do nothing;
create table if not exists public.pal_ns_maintenance (id uuid primary key default gen_random_uuid(),tenant text not null default 'newstart' check(tenant='newstart'),house_id integer not null references public.pal_ns_houses(id),job_seq integer not null,job_number text not null,title text not null,description text,urgency text not null default 'Low' check(urgency in ('High','Medium','Low')),comments text,status text not null default 'Not Yet Started' check(status in ('Not Yet Started','In Progress','Complete')),kind text not null default 'request',checklist jsonb not null default '{}'::jsonb,completion_notes text,completed_at timestamptz,created_by text,updated_by text,created_at timestamptz not null default now(),updated_at timestamptz,unique(house_id,job_seq));
create table if not exists public.pal_ns_employees(id uuid primary key default gen_random_uuid(),tenant text not null default 'newstart' check(tenant='newstart'),name text not null,employee_code text,phone text,email text,position text,house_id integer references public.pal_ns_houses(id),driver boolean default false,expected_hours numeric(6,2),pay_type text default 'Hourly',active boolean default true,created_by text,created_at timestamptz default now(),updated_at timestamptz);
create table if not exists public.pal_ns_clients(id uuid primary key default gen_random_uuid(),tenant text not null default 'newstart' check(tenant='newstart'),name text not null,house_id integer references public.pal_ns_houses(id),favorite_meals text,preferences text,active boolean default true,created_by text,created_at timestamptz default now(),updated_at timestamptz);
create table if not exists public.pal_ns_inspections(id uuid primary key default gen_random_uuid(),tenant text not null default 'newstart' check(tenant='newstart'),house_id integer not null references public.pal_ns_houses(id),period_start timestamptz not null default now(),period_end timestamptz,status text not null default 'Open',snapshot jsonb not null default '{}'::jsonb,closed_by text,created_at timestamptz default now());
create unique index if not exists pal_ns_one_open_inspection on public.pal_ns_inspections(house_id) where status='Open';
create table if not exists public.pal_ns_payroll(id uuid primary key default gen_random_uuid(),tenant text not null default 'newstart' check(tenant='newstart'),file_name text not null,storage_path text,uploaded_at timestamptz default now(),status text default 'Uploaded',notes text,created_by text,created_at timestamptz default now());
create table if not exists public.pal_ns_recipes(id uuid primary key default gen_random_uuid(),tenant text not null default 'newstart' check(tenant='newstart'),house_id integer references public.pal_ns_houses(id),client_id uuid references public.pal_ns_clients(id),name text not null,meal_type text,ingredients jsonb default '[]'::jsonb,servings integer default 1,notes text,created_by text,created_at timestamptz default now(),updated_at timestamptz);
create table if not exists public.pal_ns_menus(id uuid primary key default gen_random_uuid(),tenant text not null default 'newstart' check(tenant='newstart'),house_id integer references public.pal_ns_houses(id),week_start date not null,entries jsonb default '[]'::jsonb,notes text,created_by text,created_at timestamptz default now(),updated_at timestamptz);
create table if not exists public.pal_ns_shopping(id uuid primary key default gen_random_uuid(),tenant text not null default 'newstart' check(tenant='newstart'),house_id integer references public.pal_ns_houses(id),week_start date not null,items jsonb default '[]'::jsonb,inventory_confirmed boolean default false,confirmed_by text,approved_by text,approved_at timestamptz,created_by text,created_at timestamptz default now(),updated_at timestamptz);
-- Service role is used by the existing server; direct client access is denied.
do $$ declare t text; begin foreach t in array array['pal_ns_houses','pal_ns_maintenance','pal_ns_employees','pal_ns_clients','pal_ns_inspections','pal_ns_payroll','pal_ns_recipes','pal_ns_menus','pal_ns_shopping'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on public.%I from anon,authenticated',t); end loop; end $$;
-- Advisory lock serializes numbering within each house.
create or replace function public.pal_ns_create_maintenance(p_house_id integer,p_title text,p_description text,p_urgency text,p_comments text,p_actor text) returns jsonb language plpgsql security definer set search_path=public as $$ declare n integer; r public.pal_ns_maintenance; h text; begin if p_house_id not between 1 and 11 or p_urgency not in ('High','Medium','Low') or nullif(trim(p_title),'') is null then raise exception 'Invalid request'; end if; perform pg_advisory_xact_lock(90501,p_house_id); select coalesce(max(job_seq),0)+1 into n from public.pal_ns_maintenance where house_id=p_house_id; select name into h from public.pal_ns_houses where id=p_house_id; insert into public.pal_ns_maintenance(house_id,job_seq,job_number,title,description,urgency,comments,created_by) values(p_house_id,n,h||'-'||lpad(n::text,5,'0'),p_title,p_description,p_urgency,p_comments,p_actor) returning * into r; return to_jsonb(r); end $$;
create or replace function public.pal_ns_close_inspection(p_house_id integer,p_actor text) returns jsonb language plpgsql security definer set search_path=public as $$ declare r public.pal_ns_inspections; snap jsonb; begin if p_house_id not between 1 and 10 then raise exception 'Invalid house'; end if; perform pg_advisory_xact_lock(90502,p_house_id); select * into r from public.pal_ns_inspections where house_id=p_house_id and status='Open' for update; if not found then insert into public.pal_ns_inspections(house_id) values(p_house_id) returning * into r; end if; select coalesce(jsonb_agg(to_jsonb(m) order by m.completed_at),'[]'::jsonb) into snap from public.pal_ns_maintenance m where m.house_id=p_house_id and m.status='Complete' and m.completed_at>=r.period_start and m.completed_at<=now(); update public.pal_ns_inspections set status='Closed',period_end=now(),closed_by=p_actor,snapshot=jsonb_build_object('maintenance',snap) where id=r.id returning * into r; insert into public.pal_ns_inspections(house_id) values(p_house_id); return to_jsonb(r); end $$;
revoke all on function public.pal_ns_create_maintenance(integer,text,text,text,text,text) from public,anon,authenticated;
revoke all on function public.pal_ns_close_inspection(integer,text) from public,anon,authenticated;
grant execute on function public.pal_ns_create_maintenance(integer,text,text,text,text,text) to service_role;
grant execute on function public.pal_ns_close_inspection(integer,text) to service_role;

-- Newstart-only enhancements. No shared or BAA objects altered.
alter table public.pal_ns_employees add column if not exists responsibilities text;
alter table public.pal_ns_shopping add column if not exists approval_name text;
alter table public.pal_ns_shopping add column if not exists estimated_total numeric(12,2);
create table if not exists public.pal_ns_utility_readings(id uuid primary key default gen_random_uuid(),tenant text not null default 'newstart' check(tenant='newstart'),house_id integer not null references public.pal_ns_houses(id),period date not null,water_usage numeric(14,2),electric_kwh numeric(14,2),water_cost numeric(12,2),electric_cost numeric(12,2),notes text,created_by text,created_at timestamptz default now());
create table if not exists public.pal_ns_contracts(id uuid primary key default gen_random_uuid(),tenant text not null default 'newstart' check(tenant='newstart'),category text not null default 'Lease',party text not null,house_id integer references public.pal_ns_houses(id),expires_on date,notice_days integer default 60,notes text,created_by text,created_at timestamptz default now(),updated_at timestamptz);
alter table public.pal_ns_utility_readings enable row level security;
alter table public.pal_ns_contracts enable row level security;
revoke all on public.pal_ns_utility_readings,public.pal_ns_contracts from anon,authenticated;
-- Idempotent checklist creation, serialized per house and month. Execute via Newstart manager endpoint.
create or replace function public.pal_ns_ensure_monthly(p_month date,p_actor text) returns integer language plpgsql security definer set search_path=public as $$ declare h record; n integer; cnt integer:=0; job text; begin
 if p_month<>date_trunc('month',p_month)::date then raise exception 'Month must begin on first'; end if;
 for h in select id,name from public.pal_ns_houses where id<=10 order by id loop
  perform pg_advisory_xact_lock(90501,h.id);
  if not exists(select 1 from public.pal_ns_maintenance where house_id=h.id and kind='monthly' and date_trunc('month',created_at at time zone 'UTC')::date=p_month) then
   select coalesce(max(job_seq),0)+1 into n from public.pal_ns_maintenance where house_id=h.id;
   job:=h.name||'-'||lpad(n::text,5,'0');
   insert into public.pal_ns_maintenance(house_id,job_seq,job_number,title,description,urgency,kind,checklist,created_by,created_at)
   values(h.id,n,job,'Monthly Maintenance','Monthly checklist — record each item and completion notes','Medium','monthly','{"items":[],"template":"Monthly Maintenance"}'::jsonb,p_actor,p_month::timestamptz);
   cnt:=cnt+1;
  end if;
 end loop;
 return cnt; end $$;
revoke all on function public.pal_ns_ensure_monthly(date,text) from public,anon,authenticated;
grant execute on function public.pal_ns_ensure_monthly(date,text) to service_role;
